import test from 'node:test';import assert from 'node:assert/strict';import path from 'node:path';import fs from 'node:fs';import {createHash} from 'node:crypto';
import {planCreationGroundUpgrade,verifyCreationGroundUpgrade,CREATION_GROUND_OLD_PINS} from '../electron/main/creation-ground-upgrade.ts';
const resourcesRoot=path.resolve(import.meta.dirname,'../../../../../desktop/godot');
const pin=(path,text)=>({path,sha256:createHash('sha256').update(text).digest('hex'),bytes:Buffer.byteLength(text)});
const formal=[{path:'scripts/creation_world.gd',sha256:CREATION_GROUND_OLD_PINS[0],bytes:26575},pin('world/creation.json','authored-scene'),pin('scripts/creation/rules/custom.gd','authored-rule')];
const plan=(changes={})=>planCreationGroundUpgrade({baseId:'creation-sandbox',formalFiles:formal,draftFiles:structuredClone(formal),resourcesRoot,...changes});
test('exact stock upgrade plans one source write; all authored content is retained',()=>{const result=plan();assert.equal(result.status,'planned');assert.equal(result.operations.length,1);assert.equal(result.operations[0].expectedHash,formal[0].sha256);assert.match(result.operations[0].text,/Color\("4f6b5a"\)/);assert.match(result.operations[0].text,/ambient_light_energy = 0.55/);assert.deepEqual(result.expectedFiles.slice(1),formal.slice(1));verifyCreationGroundUpgrade(result,result.expectedFiles);});
test('unrelated uncommitted draft blocks upgrade without a write',()=>assert.deepEqual(plan({draftFiles:[...formal,pin('notes.txt','valuable draft')]}),{status:'skipped',reason:'draft-conflict'}));
test('custom scripts never qualify by a copied managed-base manifest',()=>assert.deepEqual(plan({formalFiles:[pin('scripts/creation_world.gd','Color("6e9580")'),...formal.slice(1)]}),{status:'skipped',reason:'customized-source'}));
test('both released line ending cohorts are accepted',()=>{const files=[{...formal[0],sha256:CREATION_GROUND_OLD_PINS[1]},...formal.slice(1)];assert.equal(plan({formalFiles:files,draftFiles:files}).status,'planned');});
test('released source pins match the complete pre-fix stock file',()=>{const text=fs.readFileSync(path.join(resourcesRoot,'bases/creation-sandbox/scripts/creation_world.gd'),'utf8').replace(/\r\n/g,'\n').replace('F2 对话 · Shift+F2 工作台','F2 创作').replace('ambient_light_energy = 0.55','ambient_light_energy = 0.7').replace('Color("4f6b5a")','Color("6e9580")');assert.equal(pin('',text).sha256,CREATION_GROUND_OLD_PINS[0]);assert.equal(pin('',text.replace(/\n/g,'\r\n')).sha256,CREATION_GROUND_OLD_PINS[1]);});
test('already current stock is idempotent',()=>{const text=fs.readFileSync(path.join(resourcesRoot,'bases/creation-sandbox/scripts/creation_world.gd'),'utf8');const files=[pin('scripts/creation_world.gd',text),...formal.slice(1)];assert.deepEqual(plan({formalFiles:files,draftFiles:files}),{status:'skipped',reason:'already-current'});});
test('case collisions and changed post-patch sources are rejected',()=>{assert.throws(()=>plan({draftFiles:[...formal,{...formal[0],path:'Scripts/creation_world.gd'}]}),/MANIFEST_INVALID/);const result=plan();assert.throws(()=>verifyCreationGroundUpgrade(result,[...result.expectedFiles,pin('notes.txt','new draft')]),/SOURCE_CHANGED/);});
